head.b:skin:
/* ===== tokens (src/css/variables.css) ===== */
:root {
  --color-primary:#2563EB; --color-primary-dark:#1D4ED8; --color-primary-soft:#EFF6FF;
  --color-text:#111827; --color-text-secondary:#6B7280; --color-text-strong:#4B5563;
  --color-text-muted:#9CA3AF; --color-text-inverse:#FFFFFF;
  --color-background:#FFFFFF; --color-surface:#F8FAFC; --color-border:#E5E7EB;
  --color-success:#16A34A; --color-danger:#DC2626;
  --color-footer-bg:#0F172A; --color-footer-heading:#FFFFFF;
  --color-footer-text:#CBD5E1; --color-footer-muted:#94A3B8;
  --font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --text-h1:30px; --text-h2:22px; --text-h3:18px; --text-body:16px;
  --text-card-title:17px; --text-card-summary:14px; --text-meta:12px;
  --text-nav:15px; --leading-tight:1.15; --leading-body:1.7;
  --weight-medium:500; --weight-semibold:600; --weight-bold:700;
  --container-width:1180px; --container-gutter:32px;
  --article-width:730px; --sidebar-width:300px; --header-height:60px;
  --space-xs:4px; --space-sm:8px; --space-md:16px; --space-lg:24px;
  --space-xl:32px; --space-2xl:40px; --space-section:40px;
  --radius-sm:6px; --radius-md:8px; --radius-lg:12px;
  --shadow-sm:0 1px 2px rgba(17,24,39,.06); --shadow-md:0 8px 24px rgba(17,24,39,.08);
  --transition-fast:150ms ease; --transition:220ms ease;
  --z-header:100; --z-drawer:200; --target-min:44px;
}
@media (min-width:768px) and (max-width:1023px) {
  :root { --text-h1:38px; --text-h2:26px; --text-h3:20px; --text-body:17px;
    --text-card-title:18px; --text-card-summary:15px; --header-height:64px;
    --space-section:48px; --container-gutter:40px; }
}
@media (min-width:1024px) and (max-width:1279px) {
  :root { --text-h1:46px; --text-h2:30px; --text-h3:22px; --text-body:18px;
    --text-card-title:20px; --text-card-summary:15px; --text-meta:13px;
    --header-height:68px; --space-section:56px; --container-gutter:40px; }
}
@media (min-width:1280px) {
  :root { --text-h1:50px; --text-h2:32px; --text-h3:24px; --text-body:18px;
    --text-card-title:21px; --text-card-summary:16px; --text-meta:13px;
    --header-height:68px; --space-section:64px; --container-width:1200px;
    --container-gutter:40px; }
}

/* ===== reset + base (src/css/reset.css, base.css) ===== */
*,*::before,*::after{box-sizing:border-box}
*{margin:0}
html{-webkit-text-size-adjust:100%}
body{min-height:100vh;font-family:var(--font-family);font-size:var(--text-body);
  line-height:var(--leading-body);color:var(--color-text);background:var(--color-background);
  -webkit-font-smoothing:antialiased}
img,picture,video,canvas{display:block;max-width:100%;height:auto}
svg{display:block;max-width:100%}
input,button,textarea,select{font:inherit;color:inherit}
button{background:none;border:0;padding:0;cursor:pointer}
ul,ol{list-style:none;padding:0}
a{color:var(--color-primary);text-decoration:none;transition:color var(--transition-fast)}
a:hover{color:var(--color-primary-dark)}
p,h1,h2,h3,h4,h5,h6{overflow-wrap:break-word}
:focus-visible{outline:3px solid var(--color-primary);outline-offset:2px;border-radius:3px}
.container{width:calc(100% - var(--container-gutter));margin-inline:auto}
h1,.h1{font-size:var(--text-h1);line-height:var(--leading-tight);font-weight:var(--weight-bold);letter-spacing:-.02em}
h2,.h2{font-size:var(--text-h2);line-height:1.2;font-weight:var(--weight-bold);letter-spacing:-.01em}
h3,.h3{font-size:var(--text-h3);line-height:1.3;font-weight:var(--weight-semibold)}
.eyebrow{display:inline-block;font-size:var(--text-meta);font-weight:var(--weight-semibold);
  letter-spacing:.08em;text-transform:uppercase;color:var(--color-primary)}
.meta{font-size:var(--text-meta);line-height:1.5;color:var(--color-text-secondary)}
.meta--dot > * + *::before{content:"·";margin-inline:6px;color:var(--color-text-muted)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-sm);
  min-height:var(--target-min);padding:0 20px;border-radius:var(--radius-sm);font-size:15px;
  font-weight:var(--weight-semibold);line-height:1;transition:background-color var(--transition-fast),color var(--transition-fast)}
.btn--primary{background:var(--color-primary);color:var(--color-text-inverse)}
.btn--primary:hover{background:var(--color-primary-dark);color:var(--color-text-inverse)}
.btn--ghost{background:var(--color-background);border:1px solid var(--color-border);color:var(--color-text)}
.btn--ghost:hover{border-color:var(--color-primary);color:var(--color-primary)}
.field{width:100%;min-height:var(--target-min);padding:10px 14px;background:var(--color-background);
  border:1px solid var(--color-border);border-radius:var(--radius-sm);font-size:15px}
.field::placeholder{color:var(--color-text-muted)}
.field:focus{outline:none;border-color:var(--color-primary);box-shadow:0 0 0 3px var(--color-primary-soft)}
section.section{padding-block:var(--space-section)}
.section--surface{background:var(--color-surface)}
.section-header{display:flex;align-items:baseline;justify-content:space-between;gap:var(--space-md);
  margin-bottom:var(--space-lg);padding-bottom:12px;border-bottom:2px solid var(--color-border)}
.section-title{font-size:var(--text-h2)}
.section-link{font-size:14px;font-weight:var(--weight-semibold);white-space:nowrap}
.ad-slot{display:flex;align-items:center;justify-content:center;min-height:100px;
  background:var(--color-surface);border:1px dashed var(--color-border);border-radius:var(--radius-md);
  color:var(--color-text-secondary);font-size:11px;letter-spacing:.1em;text-transform:uppercase}
.ad-slot--sidebar{min-height:250px}
.ad-wrap{padding-block:var(--space-lg)}
.skip-link{position:absolute;left:-9999px;top:0;z-index:var(--z-drawer);padding:12px 18px;
  background:var(--color-primary);color:var(--color-text-inverse);font-weight:var(--weight-semibold)}
.skip-link:focus{left:8px;top:8px}
.visually-hidden{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

/* ===== header + navegação (src/css/header.css, navigation.css) ===== */
.site-header{position:relative;z-index:var(--z-header);background:var(--color-background);
  border-bottom:1px solid var(--color-border)}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:var(--space-md);
  min-height:var(--header-height)}
.site-logo{display:inline-flex;align-items:center;flex-shrink:0;min-height:var(--target-min)}
.site-logo img{height:auto;max-height:30px;width:auto;max-width:220px}
.site-title{font-size:20px;font-weight:var(--weight-bold);color:var(--color-text)}
.header-actions{display:flex;align-items:center;gap:var(--space-xs)}
.header-search,.menu-toggle{display:inline-flex;align-items:center;justify-content:center;
  width:var(--target-min);height:var(--target-min);color:var(--color-text);border-radius:var(--radius-sm)}
.header-search:hover,.menu-toggle:hover{background:var(--color-surface);color:var(--color-primary)}
.header-search svg,.menu-toggle svg{width:20px;height:20px}
.menu-toggle .icon-close{display:none}
.menu-toggle[aria-expanded="true"] .icon-menu{display:none}
.menu-toggle[aria-expanded="true"] .icon-close{display:block}
.nav-backdrop{position:fixed;inset:0;background:rgba(17,24,39,.45);opacity:0;visibility:hidden;
  transition:opacity var(--transition),visibility var(--transition)}
.nav-backdrop.is-open{opacity:1;visibility:visible}
.main-nav{position:fixed;top:0;right:0;z-index:calc(var(--z-drawer) + 1);width:min(320px,85vw);
  height:100dvh;padding:calc(var(--header-height) + 16px) 20px 24px;background:var(--color-background);
  box-shadow:var(--shadow-md);overflow-y:auto;transform:translateX(100%);visibility:hidden;
  transition:transform var(--transition),visibility var(--transition)}
.main-nav.is-open{transform:translateX(0);visibility:visible}
.nav-list{display:flex;flex-direction:column;gap:var(--space-xs)}
.nav-link{position:relative;display:flex;align-items:center;min-height:var(--target-min);
  padding:0 10px;border-radius:var(--radius-sm);font-size:var(--text-nav);
  font-weight:var(--weight-semibold);color:var(--color-text)}
.nav-link:hover{background:var(--color-surface);color:var(--color-primary)}
.nav-link.is-active{color:var(--color-primary);font-weight:var(--weight-bold)}

/* ===== cartões e grelhas (src/css/cards.css, sections.css) ===== */
.card-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--space-lg)}
.card{display:flex;flex-direction:column;gap:var(--space-sm);min-width:0}
.card-media{display:block;overflow:hidden;border-radius:var(--radius-md);background:var(--color-surface)}
.card-media img{width:100%;aspect-ratio:16 / 9;object-fit:cover}
.card-body{display:flex;flex-direction:column;gap:var(--space-sm);min-width:0}
.card-title{font-size:var(--text-card-title);line-height:1.3;font-weight:var(--weight-semibold)}
.card-title a{color:var(--color-text)}
.card-title a:hover{color:var(--color-primary)}
.card-summary{font-size:var(--text-card-summary);line-height:1.6;color:var(--color-text-secondary)}
.card-meta{margin-top:auto;font-size:var(--text-meta);color:var(--color-text-secondary)}
.card--featured .card-title{font-size:var(--text-h3);line-height:1.25;font-weight:var(--weight-bold)}
.card--row{display:grid;grid-template-columns:120px minmax(0,1fr);gap:var(--space-md);
  align-items:start;padding-block:var(--space-md);border-bottom:1px solid var(--color-border)}
.card--row .card-media img{aspect-ratio:4 / 3}
.card--row .card-title{font-size:calc(var(--text-card-title) - 1px)}
.card--row .card-summary{display:none}
.category-split{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--space-lg)}
.split-secondary{display:flex;flex-direction:column}
.newsletter{display:grid;gap:var(--space-lg);padding:var(--space-xl);background:var(--color-surface);
  border:1px solid var(--color-border);border-radius:var(--radius-lg)}
.newsletter-title{font-size:var(--text-h3)}
.newsletter-text{margin-top:var(--space-xs);font-size:var(--text-card-summary);color:var(--color-text-secondary)}
.newsletter-form{display:flex;flex-direction:column;gap:var(--space-sm)}
.newsletter-form .field{flex:1 1 auto;min-width:0}
.newsletter-note{font-size:var(--text-meta);color:var(--color-text-secondary)}
.pagination{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:var(--space-sm);
  margin-top:var(--space-xl)}
.pagination a,.pagination span{display:inline-flex;align-items:center;justify-content:center;
  min-width:var(--target-min);min-height:var(--target-min);padding:0 12px;
  border:1px solid var(--color-border);border-radius:var(--radius-sm);font-size:14px;
  font-weight:var(--weight-semibold);color:var(--color-text)}
.pagination a:hover{border-color:var(--color-primary);color:var(--color-primary)}
.pagination [aria-current="page"]{background:var(--color-primary);border-color:var(--color-primary);
  color:var(--color-text-inverse)}

/* ===== hero (src/css/hero.css) ===== */
.hero{padding-block:var(--space-section)}
.hero-grid{display:grid;gap:var(--space-lg)}
.hero-media{display:block;overflow:hidden;border-radius:var(--radius-md);background:var(--color-surface)}
.hero-media img{width:100%;aspect-ratio:16 / 9;object-fit:cover}
.hero-content{display:flex;flex-direction:column;align-items:flex-start;gap:var(--space-md)}
.hero-title{font-size:var(--text-h1);line-height:var(--leading-tight)}
.hero-title a{color:var(--color-text)}
.hero-title a:hover{color:var(--color-primary)}
.hero-summary{font-size:var(--text-body);line-height:1.65;color:var(--color-text-secondary)}

/* ===== layout + sidebar (src/css/sidebar.css) ===== */
.main-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--space-2xl);
  padding-block:var(--space-section)}
.main-content{min-width:0}
.sidebar{display:flex;flex-direction:column;gap:var(--space-xl);min-width:0}
.container:not(.main-layout) > .sidebar{display:none}
.widget{padding:var(--space-lg);background:var(--color-background);border:1px solid var(--color-border);
  border-radius:var(--radius-md)}
.widget--plain{padding:0;border:0}
.widget-title{margin-bottom:var(--space-md);padding-bottom:var(--space-sm);
  border-bottom:2px solid var(--color-border);font-size:15px;font-weight:var(--weight-bold);
  letter-spacing:.04em;text-transform:uppercase}
.search-form{display:flex;gap:var(--space-sm)}
.search-form .field{flex:1 1 auto;min-width:0}
.search-form .btn{flex-shrink:0;padding-inline:16px}
.recent-list{display:flex;flex-direction:column;gap:var(--space-md)}
.recent-item{display:grid;grid-template-columns:72px minmax(0,1fr);gap:var(--space-sm);align-items:start}
.recent-thumb{width:72px;height:52px;overflow:hidden;border-radius:var(--radius-sm);background:var(--color-surface)}
.recent-thumb img{width:72px;height:52px;object-fit:cover}
.recent-title{display:block;font-size:14px;line-height:1.35;font-weight:var(--weight-semibold)}
.recent-title a{color:var(--color-text)}
.recent-title a:hover{color:var(--color-primary)}
.recent-meta{display:block;margin-top:2px;font-size:11px;color:var(--color-text-secondary)}
.category-list a{display:flex;align-items:center;justify-content:space-between;gap:var(--space-sm);
  min-height:var(--target-min);padding-block:6px;border-bottom:1px solid var(--color-border);
  font-size:14px;font-weight:var(--weight-medium);color:var(--color-text)}
.category-list li:last-child a{border-bottom:0}
.category-list a:hover{color:var(--color-primary)}
.category-list .count{font-size:12px;color:var(--color-text-secondary)}
.widget-calc{display:flex;flex-direction:column;gap:var(--space-sm);padding:var(--space-lg);
  background:var(--color-primary-soft);border:1px solid var(--color-primary);border-radius:var(--radius-md)}
.widget-calc .widget-title{border-bottom-color:rgba(37,99,235,.3);color:var(--color-primary-dark)}
.widget-calc p{font-size:var(--text-card-summary);color:var(--color-text-strong)}

/* ===== calculadoras (src/css/calculators.css) ===== */
.calc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,150px),1fr));gap:var(--space-md)}
.calc-card{display:flex;flex-direction:column;align-items:flex-start;gap:var(--space-md);
  min-height:120px;padding:20px;background:var(--color-background);border:1px solid var(--color-border);
  border-radius:var(--radius-md);color:var(--color-text)}
.calc-card:hover{border-color:var(--color-primary);box-shadow:var(--shadow-sm);color:var(--color-text)}
.calc-icon{flex-shrink:0;display:grid;place-items:center;width:44px;height:44px;
  background:var(--color-primary-soft);border-radius:var(--radius-sm);color:var(--color-primary)}
.calc-icon svg{width:22px;height:22px}
.calc-body{flex:1 1 auto;min-width:0}
.calc-name{display:block;font-size:calc(var(--text-card-title) - 1px);font-weight:var(--weight-semibold);
  line-height:1.3;overflow-wrap:break-word}
.calc-desc{display:block;margin-top:var(--space-xs);font-size:var(--text-meta);line-height:1.5;
  color:var(--color-text-secondary);overflow-wrap:break-word}
.calc-arrow{flex-shrink:0;align-self:flex-end;color:var(--color-text-muted)}
.calc-arrow svg{width:18px;height:18px}
.calc-card:hover .calc-arrow{color:var(--color-primary)}

/* ===== artigo (src/css/article.css) ===== */
.breadcrumb{padding-block:var(--space-md);font-size:var(--text-meta);color:var(--color-text-secondary)}
.breadcrumb ol{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.breadcrumb li + li::before{content:"/";margin-right:6px;color:var(--color-text-muted)}
.breadcrumb [aria-current="page"]{color:var(--color-text);font-weight:var(--weight-medium)}
.article-header{display:flex;flex-direction:column;gap:var(--space-md);max-width:var(--article-width);
  margin-inline:auto}
.article-title{font-size:var(--text-h1);line-height:var(--leading-tight)}
.article-summary{font-size:calc(var(--text-body) + 1px);line-height:1.6;color:var(--color-text-secondary)}
.article-figure{margin-block:var(--space-lg)}
.article-figure img{width:100%;aspect-ratio:16 / 9;object-fit:cover;border-radius:var(--radius-md);
  background:var(--color-surface)}
.article-figure figcaption{margin-top:var(--space-sm);font-size:var(--text-meta);color:var(--color-text-secondary)}
.article-body{max-width:var(--article-width);margin-inline:auto;font-size:var(--text-body);line-height:var(--leading-body)}
.article-body > * + *{margin-top:var(--space-md)}
.article-body h2{margin-top:var(--space-xl);font-size:var(--text-h2);line-height:1.25}
.article-body h3{margin-top:var(--space-lg);font-size:var(--text-h3);line-height:1.3}
.article-body ul{list-style:disc;padding-left:22px}
.article-body ol{list-style:decimal;padding-left:22px}
.article-body li + li{margin-top:6px}
.article-body blockquote{padding:var(--space-md) var(--space-lg);background:var(--color-surface);
  border-left:4px solid var(--color-primary);border-radius:var(--radius-sm);font-style:italic;
  color:var(--color-text-secondary)}
.article-body a{text-decoration:underline;text-underline-offset:2px}
.page-header{display:flex;flex-direction:column;gap:var(--space-sm);padding-bottom:var(--space-lg);
  margin-bottom:var(--space-lg);border-bottom:2px solid var(--color-border)}
.page-description{max-width:720px;font-size:var(--text-card-summary);line-height:1.6;color:var(--color-text-secondary)}

/* ===== footer (src/css/footer.css) ===== */
.site-footer{margin-top:var(--space-section);background:var(--color-footer-bg);color:var(--color-footer-text)}
.footer-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--space-xl);padding-block:48px}
.footer-brand-name{font-size:calc(var(--text-h3) - 2px);font-weight:var(--weight-bold);color:var(--color-footer-heading)}
.footer-text{margin-top:var(--space-sm);font-size:var(--text-card-summary);line-height:1.6;color:var(--color-footer-text)}
.footer-title{margin-bottom:var(--space-sm);font-size:14px;font-weight:var(--weight-bold);
  letter-spacing:.06em;text-transform:uppercase;color:var(--color-footer-heading)}
.footer-links{display:flex;flex-direction:column}
.footer-links a{display:flex;align-items:center;min-height:var(--target-min);font-size:15px;color:var(--color-footer-text)}
.footer-links a:hover{color:var(--color-footer-heading);text-decoration:underline;text-underline-offset:3px}
.footer-bottom{display:flex;flex-direction:column;gap:var(--space-sm);padding-block:var(--space-lg);
  border-top:1px solid rgba(255,255,255,.12);font-size:13px;color:var(--color-footer-muted)}
.footer-bottom a{color:var(--color-footer-muted)}
.footer-bottom a:hover{color:var(--color-footer-heading)}
.footer-disclaimer{max-width:760px;line-height:1.6}

/* ===== responsividade — 4 breakpoints (src/css/responsive.css) ===== */
@media (max-width:767px){
  .newsletter{padding:var(--space-lg)}
  .card--row{grid-template-columns:96px minmax(0,1fr);gap:12px}
  .footer-grid{padding-block:40px}
  .widget{padding:var(--space-md)}
}
@media (min-width:768px) and (max-width:1023px){
  .container{width:min(var(--container-width),calc(100% - 40px))}
  .hero-grid{grid-template-columns:minmax(0,55fr) minmax(0,45fr);gap:var(--space-lg);align-items:center}
  .card-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
  .category-split{grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:var(--space-lg)}
  .calc-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
  .calc-card{flex-direction:row;align-items:center}
  .calc-arrow{align-self:center}
  .newsletter{grid-template-columns:minmax(0,1fr) minmax(0,340px);align-items:center;padding:var(--space-xl)}
  .newsletter-form{flex-direction:row}
  .footer-grid{grid-template-columns:repeat(2,minmax(0,1fr));padding-block:56px}
}
@media (min-width:1024px){
  .container{width:min(var(--container-width),calc(100% - 40px))}
  .main-nav{position:static;width:auto;height:auto;padding:0;background:none;box-shadow:none;
    overflow:visible;transform:none;visibility:visible;transition:none}
  .nav-list{flex-direction:row;gap:24px}
  .nav-link{padding:0 2px}
  .nav-link:hover{background:none}
  .menu-toggle,.nav-backdrop{display:none}
  .header-inner{gap:var(--space-xl)}
  .hero-grid{grid-template-columns:minmax(0,55fr) minmax(0,45fr);gap:28px;align-items:center}
  .card-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
  .category-split{grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:var(--space-lg)}
  .main-layout{grid-template-columns:minmax(0,1fr) var(--sidebar-width);gap:var(--space-2xl)}
  .calc-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
  .calc-form{grid-template-columns:repeat(2,minmax(0,1fr))}
  .newsletter{grid-template-columns:minmax(0,1fr) minmax(0,380px);align-items:center}
  .footer-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--space-2xl);padding-block:56px}
  .footer-bottom{flex-direction:row;justify-content:space-between;align-items:center}
}
@media (min-width:1280px){
  .container{width:min(var(--container-width),calc(100% - 40px))}
  .hero-grid{gap:var(--space-xl)}
  .card-grid{gap:var(--space-lg)}
  .calc-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
  .footer-grid{padding-block:64px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition-duration:1ms!important;animation-duration:1ms!important}
}

body.script:
//
(function () {
  var toggle = document.querySelector('.menu-toggle');
  var nav = document.getElementById('main-nav');
  var backdrop = document.querySelector('.nav-backdrop');
  if (!toggle || !nav) return;
  var lastFocused = null;

  function isOpen() { return nav.classList.contains('is-open'); }

  function focusables() {
    return [toggle].concat(Array.prototype.slice.call(
      nav.querySelectorAll('a[href], button:not([disabled])')));
  }

  function open() {
    lastFocused = document.activeElement;
    nav.classList.add('is-open');
    if (backdrop) backdrop.classList.add('is-open');
    toggle.setAttribute('aria-expanded', 'true');
    toggle.setAttribute('aria-label', 'Fechar menu');
    document.body.style.overflow = 'hidden';
    var first = nav.querySelector('a[href]');
    if (first) first.focus();
  }

  function close(restore) {
    nav.classList.remove('is-open');
    if (backdrop) backdrop.classList.remove('is-open');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.setAttribute('aria-label', 'Abrir menu');
    document.body.style.overflow = '';
    if (restore !== false && lastFocused && lastFocused.focus) lastFocused.focus();
  }

  toggle.addEventListener('click', function () { isOpen() ? close() : open(); });
  if (backdrop) backdrop.addEventListener('click', function () { close(); });
  nav.addEventListener('click', function (e) {
    if (e.target.closest && e.target.closest('a[href]')) close(false);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && isOpen()) { close(); return; }
    if (e.key !== 'Tab' || !isOpen()) return;
    var items = focusables();
    var first = items[0], last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  });
})();

// FAQPage — emitida só se o artigo tiver mesmo perguntas visíveis no corpo.
// Lê as <details> do post (marcadas no editor HTML do Blogger) e constrói o
// JSON-LD com o texto real da página; sem FAQ, não há script.
(function () {
  var body = document.querySelector('.article-body');
  if (!body) return;
  var nodes = body.querySelectorAll('details');
  var items = [];
  for (var i = 0; i < nodes.length; i++) {
    var det = nodes[i];
    var sum = det.querySelector('summary');
    if (!sum || sum.getClientRects().length === 0) continue;
    var name = (sum.textContent || '').trim();
    var ans = det.querySelector('.faq-answer') || det;
    var text = (ans.textContent || '').replace(name, '').trim();
    if (!name || !text) continue;
    items.push({ '@type': 'Question', name: name,
      acceptedAnswer: { '@type': 'Answer', text: text } });
  }
  if (!items.length) return;
  var s = document.createElement('script');
  s.type = 'application/ld+json';
  s.textContent = JSON.stringify({ '@context': 'https://schema.org',
    '@type': 'FAQPage', mainEntity: items });
  document.head.appendChild(s);
})();
//
